import { shuffle } from './ArrayShuffle.js';

export class MemoryGame {
    // Array of different card images and names
    cardDefinitions = null;

    // Array of card objects that represent the cards on the game board
    gameCards = [];

    // Value of the timer displayed to the user
    gameTime = 0;

    // Reference to the timer object that will be generated by a call to setInterval
    gameTimer = null;

    // Stores the promise from the fetch event to determine if data operations have completed
    ready = null;

    constructor(gameBoardElement, gameTimerElement, cardTemplate) {
        this.gameBoardElement = gameBoardElement;
        this.gameTimerElement = gameTimerElement;
        this.cardTemplate = cardTemplate;

        this.ready = fetch(new URL('../json/CardDef.json', import.meta.url))
            .then(response => {
                if (!response.ok) {
                    throw new Error(`Unable to load card definitions: HTTP ${response.status}`);
                }
                return response.json();
            })
            .then(data => {
                this.cardDefinitions = data;
            })
            .catch(error => console.log(error));
    }

    newGame(numMatches) {
        if (numMatches > 10) {
            alert("Number of matches cannot exceed 10");
            return;
        }

        clearInterval(this.gameTimer);
        this.gameTimer = null;

        this.gameTime = 0;
        this.gameTimerElement.textContent = 0;

        this.gameBoardElement.replaceChildren();

        this.gameCards = [];

        for (let i = 0; i < numMatches; i++) {
            for (let j = 0; j < 2; j++) {
                let card = this.cardTemplate.content.cloneNode(true);
                let cardElement = card.querySelector("li");

                cardElement.dataset.name = this.cardDefinitions[i].name;
                cardElement.dataset.url = this.cardDefinitions[i].url;

                this.gameCards.push(card);
            }
        }

        shuffle(this.gameCards);

        for (let card of this.gameCards) {
            this.gameBoardElement.append(card);
        }

        this.gameTimer = setInterval(() => {
            this.updateGameTime();
        }, 1000);
    }

    updateGameTime() {
        this.gameTime += 1;
        this.gameTimerElement.textContent = this.gameTime;
    }
}
